use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

use anyhow::{Context, Result, bail};
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Scope {
    Worktree,
    Branch,
}

/// One entry of `git log` for the history view.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CommitInfo {
    pub sha: String,
    pub short: String,
    pub author: String,
    pub date: String,
    pub subject: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ChangeKind {
    Modified,
    Added,
    Deleted,
    Renamed,
    Untracked,
    Conflicted,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StageState {
    Unstaged,
    Staged,
    Partial,
    Untracked,
    /// Branch scope / conflicts: staging is not applicable.
    NA,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FileEntry {
    /// Repo-relative; the *new* path for renames.
    pub path: PathBuf,
    pub orig_path: Option<PathBuf>,
    pub kind: ChangeKind,
    pub stage: StageState,
    /// None = binary (numstat reports `-`).
    pub adds: Option<u32>,
    pub dels: Option<u32>,
}

pub struct Repo {
    pub root: PathBuf,
}

impl Repo {
    pub fn discover(dir: &Path) -> Result<Repo> {
        let out = Command::new("git")
            .arg("-C")
            .arg(dir)
            .args(["rev-parse", "--show-toplevel"])
            .output()
            .context("spawning git")?;
        if !out.status.success() {
            bail!("{} is not inside a git repository", dir.display());
        }
        let root = PathBuf::from(String::from_utf8_lossy(&out.stdout).trim());
        Ok(Repo { root })
    }

    // ---- command wrappers -------------------------------------------------

    /// Run git, error on non-zero exit with stderr in the message.
    fn git(&self, args: &[&str]) -> Result<Vec<u8>> {
        let out = self.git_lenient(args)?;
        if !out.status.success() {
            bail!(
                "git {args:?} failed: {}",
                String::from_utf8_lossy(&out.stderr).trim()
            );
        }
        Ok(out.stdout)
    }

    /// Run git, return the raw Output regardless of exit code.
    fn git_lenient(&self, args: &[&str]) -> Result<Output> {
        Command::new("git")
            .arg("-C")
            .arg(&self.root)
            .args(args)
            .output()
            .with_context(|| format!("spawning git {args:?}"))
    }

    /// For commands where exit 1 means "differences found" / "clean absence"
    /// (e.g. `diff --no-index`): 0 and 1 are both success.
    fn git_tristate(&self, args: &[&str]) -> Result<Vec<u8>> {
        let out = self.git_lenient(args)?;
        match out.status.code() {
            Some(0) | Some(1) => Ok(out.stdout),
            _ => bail!(
                "git {args:?} failed: {}",
                String::from_utf8_lossy(&out.stderr).trim()
            ),
        }
    }

    // ---- branch / base ----------------------------------------------------

    /// Current branch name, None when detached.
    pub fn head_branch(&self) -> Option<String> {
        let out = self
            .git_lenient(&["symbolic-ref", "--quiet", "--short", "HEAD"])
            .ok()?;
        out.status
            .success()
            .then(|| String::from_utf8_lossy(&out.stdout).trim().to_string())
    }

    /// Base branch for branch scope: origin/HEAD → origin/main →
    /// origin/master → main → master. Last resort: "HEAD".
    pub fn detect_base(&self) -> String {
        if let Ok(out) = self.git_lenient(&["symbolic-ref", "refs/remotes/origin/HEAD"])
            && out.status.success()
        {
            let full = String::from_utf8_lossy(&out.stdout);
            // refs/remotes/origin/main -> origin/main
            if let Some(rest) = full.trim().strip_prefix("refs/remotes/") {
                return rest.to_string();
            }
        }
        for candidate in ["origin/main", "origin/master", "main", "master"] {
            if let Ok(out) = self.git_lenient(&["rev-parse", "--verify", "--quiet", candidate])
                && out.status.success()
            {
                return candidate.to_string();
            }
        }
        "HEAD".to_string()
    }

    pub fn merge_base(&self, base: &str) -> Result<String> {
        let out = self.git(&["merge-base", "HEAD", base])?;
        Ok(String::from_utf8_lossy(&out).trim().to_string())
    }

    // ---- worktree status --------------------------------------------------

    pub fn worktree_status(&self, show_untracked: bool) -> Result<Vec<FileEntry>> {
        let untracked = if show_untracked {
            "--untracked-files=all"
        } else {
            "--untracked-files=no"
        };
        let raw = self.git(&["status", "--porcelain=v2", "-z", untracked])?;
        let mut entries = parse_porcelain_v2(&raw)?;

        // Merge line stats from numstat (unstaged + staged, summed per path).
        let mut stats: HashMap<PathBuf, Option<(u32, u32)>> = HashMap::new();
        for args in [
            &["diff", "--numstat", "-z", "-M"][..],
            &["diff", "--numstat", "-z", "-M", "--cached"][..],
        ] {
            for (path, stat) in parse_numstat(&self.git(args)?) {
                merge_stat(&mut stats, path, stat);
            }
        }
        for entry in &mut entries {
            match entry.kind {
                ChangeKind::Untracked => {
                    let (adds, dels) = untracked_stats(&self.root.join(&entry.path));
                    entry.adds = adds;
                    entry.dels = dels;
                }
                _ => {
                    if let Some(stat) = stats.get(&entry.path) {
                        (entry.adds, entry.dels) = match stat {
                            Some((a, d)) => (Some(*a), Some(*d)),
                            None => (None, None), // binary
                        };
                    }
                }
            }
        }
        sort_entries(&mut entries);
        Ok(entries)
    }

    // ---- branch scope -----------------------------------------------------

    pub fn branch_changes(&self, merge_base: &str) -> Result<Vec<FileEntry>> {
        let raw = self.git(&["diff", merge_base, "--name-status", "-z", "-M"])?;
        let mut entries = parse_name_status(&raw)?;

        let mut stats: HashMap<PathBuf, Option<(u32, u32)>> = HashMap::new();
        let numstat = self.git(&["diff", merge_base, "--numstat", "-z", "-M"])?;
        for (path, stat) in parse_numstat(&numstat) {
            merge_stat(&mut stats, path, stat);
        }
        for entry in &mut entries {
            if let Some(stat) = stats.get(&entry.path) {
                (entry.adds, entry.dels) = match stat {
                    Some((a, d)) => (Some(*a), Some(*d)),
                    None => (None, None),
                };
            }
        }
        sort_entries(&mut entries);
        Ok(entries)
    }

    // ---- diff rendering ---------------------------------------------------

    /// Colored unified diff for one entry as raw bytes (ANSI escapes included).
    ///
    /// The command matrix (see `00-shared-contracts.md`):
    /// - worktree unstaged: `git diff -- <p>`
    /// - worktree staged view: `git diff --cached -- <p>`
    /// - untracked: `git diff --no-index -- /dev/null <p>` (exit 1 is fine)
    /// - branch scope: `git diff <merge_base> -- <p>` (renames add `-M` and
    ///   both the orig and new paths to the pathspec)
    ///
    /// Color and pager settings are forced regardless of the user's git config
    /// so the output is always colorized and never piped to a pager.
    /// Branch scope resolves its own merge base (via `detect_base` +
    /// `merge_base`) so the contract signature `diff_ansi(e, scope, cached)`
    /// is kept exactly.
    /// The diff for one entry. `commit: Some(sha)` shows that commit's change
    /// to the file (history view) and ignores `scope`/`cached`.
    pub fn diff_ansi(
        &self,
        e: &FileEntry,
        scope: Scope,
        cached: bool,
        commit: Option<&str>,
    ) -> Result<Vec<u8>> {
        let path = e.path.to_string_lossy().into_owned();
        if let Some(sha) = commit {
            // `show` handles root commits (no parent) transparently.
            let mut args: Vec<String> = vec![
                "-c".into(),
                "color.diff=always".into(),
                "-c".into(),
                "core.pager=cat".into(),
                "show".into(),
                "--color=always".into(),
                "--no-ext-diff".into(),
                "--format=".into(),
                "-M".into(),
                sha.into(),
                "--".into(),
            ];
            if let Some(orig) = &e.orig_path {
                args.push(orig.to_string_lossy().into_owned());
            }
            args.push(path);
            let refs: Vec<&str> = args.iter().map(String::as_str).collect();
            return self.git(&refs);
        }
        let mut args: Vec<String> = vec![
            "-c".into(),
            "color.diff=always".into(),
            "-c".into(),
            "core.pager=cat".into(),
            "diff".into(),
            "--color=always".into(),
            "--no-ext-diff".into(),
        ];

        let untracked = scope == Scope::Worktree && e.kind == ChangeKind::Untracked;
        match scope {
            Scope::Worktree if untracked => {
                // Compare an empty file against the untracked file: full `+` diff.
                args.push("--no-index".into());
                args.push("--".into());
                args.push("/dev/null".into());
                args.push(path);
            }
            Scope::Worktree => {
                if cached {
                    args.push("--cached".into());
                }
                args.push("--".into());
                args.push(path);
            }
            Scope::Branch => {
                // Diff the merge base against the working tree, following renames.
                let base = self.detect_base();
                let mb = self.merge_base(&base)?;
                args.push("-M".into());
                args.push(mb);
                args.push("--".into());
                if let Some(orig) = &e.orig_path {
                    args.push(orig.to_string_lossy().into_owned());
                }
                args.push(path);
            }
        }

        let refs: Vec<&str> = args.iter().map(String::as_str).collect();
        if untracked {
            // `--no-index` exits 1 when files differ — that is the normal case.
            self.git_tristate(&refs)
        } else {
            self.git(&refs)
        }
    }

    // ---- file content (for the structured diff renderer) ------------------

    /// A file's content at `rev` (e.g. `HEAD`, a sha, `<sha>^`), or at the
    /// index when `rev` is `":0"`. `None` when the path doesn't exist there.
    pub fn file_at(&self, rev: &str, path: &Path) -> Result<Option<String>> {
        let spec = format!("{rev}:{}", path.to_string_lossy());
        let out = self.git_lenient(&["show", &spec])?;
        if !out.status.success() {
            return Ok(None); // path absent at that rev (add/delete/rename)
        }
        Ok(Some(String::from_utf8_lossy(&out.stdout).into_owned()))
    }

    /// The working-tree content of a repo-relative path; `None` when missing.
    pub fn file_in_worktree(&self, path: &Path) -> Option<String> {
        let bytes = std::fs::read(self.root.join(path)).ok()?;
        Some(String::from_utf8_lossy(&bytes).into_owned())
    }

    // ---- history ----------------------------------------------------------

    /// Recent commits, newest first.
    pub fn log_commits(&self, limit: usize) -> Result<Vec<CommitInfo>> {
        let n = limit.to_string();
        let raw = self.git(&[
            "log",
            "--format=%H%x00%h%x00%an%x00%ad%x00%s%x00",
            "--date=short",
            "-n",
            &n,
        ])?;
        let text = String::from_utf8_lossy(&raw);
        let mut fields = text.split('\0');
        let mut commits = Vec::new();
        while let (Some(sha), Some(short), Some(author), Some(date), Some(subject)) = (
            fields.next(),
            fields.next(),
            fields.next(),
            fields.next(),
            fields.next(),
        ) {
            let sha = sha.trim_start(); // leading \n from the previous record
            if sha.is_empty() {
                break;
            }
            commits.push(CommitInfo {
                sha: sha.to_string(),
                short: short.to_string(),
                author: author.to_string(),
                date: date.to_string(),
                subject: subject.to_string(),
            });
        }
        Ok(commits)
    }

    /// Files changed by one commit (vs its parent; root commits work too).
    pub fn commit_files(&self, sha: &str) -> Result<Vec<FileEntry>> {
        let raw = self.git(&[
            "diff-tree",
            "-r",
            "--root",
            "--name-status",
            "-z",
            "-M",
            sha,
        ])?;
        // diff-tree prefixes its output with the commit id line; skip it.
        let body = match raw.iter().position(|b| *b == 0) {
            Some(i) if raw.get(..40).is_some_and(|s| !s.contains(&b'\t')) => &raw[i + 1..],
            _ => &raw[..],
        };
        let mut entries = parse_name_status(body)?;

        let numstat = self.git(&["diff-tree", "-r", "--root", "--numstat", "-z", "-M", sha])?;
        let nbody = match numstat.iter().position(|b| *b == 0) {
            Some(i) if numstat.get(..40).is_some_and(|s| !s.contains(&b'\t')) => &numstat[i + 1..],
            _ => &numstat[..],
        };
        let mut stats: HashMap<PathBuf, Option<(u32, u32)>> = HashMap::new();
        for (path, stat) in parse_numstat(nbody) {
            merge_stat(&mut stats, path, stat);
        }
        for entry in &mut entries {
            if let Some(stat) = stats.get(&entry.path) {
                (entry.adds, entry.dels) = match stat {
                    Some((a, d)) => (Some(*a), Some(*d)),
                    None => (None, None),
                };
            }
        }
        sort_entries(&mut entries);
        Ok(entries)
    }

    // ---- write side (phase 5) ---------------------------------------------

    pub fn stage(&self, p: &Path) -> Result<()> {
        self.git(&["add", "--", &p.to_string_lossy()])?;
        Ok(())
    }

    pub fn unstage(&self, p: &Path) -> Result<()> {
        self.git(&["restore", "--staged", "--", &p.to_string_lossy()])?;
        Ok(())
    }

    /// Throw away all changes to this entry (worktree + index), per kind.
    pub fn discard(&self, e: &FileEntry) -> Result<()> {
        let path = e.path.to_string_lossy().to_string();
        match e.kind {
            ChangeKind::Conflicted => {
                bail!("resolve the conflict in the editor first")
            }
            ChangeKind::Untracked => {
                self.git(&["clean", "-f", "--", &path])?;
            }
            ChangeKind::Renamed => {
                // Unstage restores the old path in the index; then reset the
                // old path's content and sweep the new-path remnant.
                let orig = e
                    .orig_path
                    .as_ref()
                    .map(|p| p.to_string_lossy().to_string())
                    .unwrap_or_else(|| path.clone());
                self.git(&["restore", "--staged", "--", &orig, &path])?;
                self.git(&["restore", "--", &orig])?;
                self.git(&["clean", "-f", "--", &path])?;
            }
            _ => match e.stage {
                StageState::Unstaged => {
                    self.git(&["restore", "--", &path])?;
                }
                _ => {
                    // Staged or partial: revert index first, then worktree.
                    self.git(&["restore", "--staged", "--", &path])?;
                    // Newly added files have no HEAD version to restore.
                    if e.kind == ChangeKind::Added {
                        self.git(&["clean", "-f", "--", &path])?;
                    } else {
                        self.git(&["restore", "--", &path])?;
                    }
                }
            },
        }
        Ok(())
    }

    /// Number of files with staged changes.
    pub fn staged_count(&self) -> Result<usize> {
        let out = self.git(&["diff", "--cached", "--name-only", "-z"])?;
        Ok(out.split(|b| *b == 0).filter(|s| !s.is_empty()).count())
    }

    /// `git log -1 --format=%h %s` — flavor text after a commit.
    pub fn last_commit_summary(&self) -> Option<String> {
        let out = self.git(&["log", "-1", "--format=%h %s"]).ok()?;
        let s = String::from_utf8_lossy(&out).trim().to_string();
        (!s.is_empty()).then_some(s)
    }

    // ---- change detection -------------------------------------------------

    /// Cheap fingerprint of the working tree state; a change means the file
    /// list should refresh. FNV-1a over the raw status bytes.
    pub fn fingerprint(&self) -> u64 {
        let raw = self
            .git(&["status", "--porcelain=v2", "-z", "--untracked-files=all"])
            .unwrap_or_default();
        let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
        for byte in &raw {
            hash ^= u64::from(*byte);
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
        hash
    }
}

// ---- parsers (pure functions, unit-testable) ------------------------------

/// Parse `git status --porcelain=v2 -z` output. Records are NUL-terminated;
/// rename records (`2 …`) carry one extra NUL-separated field: the orig path.
fn parse_porcelain_v2(raw: &[u8]) -> Result<Vec<FileEntry>> {
    let text = String::from_utf8_lossy(raw);
    let mut fields = text.split('\0');
    let mut entries = Vec::new();

    while let Some(record) = fields.next() {
        if record.is_empty() {
            continue;
        }
        let mut entry = match record.chars().next() {
            Some('1') => {
                let (xy, path) = split_ordinary(record, 8)?;
                FileEntry {
                    path: PathBuf::from(path),
                    orig_path: None,
                    kind: kind_from_xy(xy),
                    stage: stage_from_xy(xy),
                    adds: None,
                    dels: None,
                }
            }
            Some('2') => {
                // `2 XY sub mH mI mW hH hI Xscore path` + NUL + origPath
                let (xy, path) = split_ordinary(record, 9)?;
                let orig = fields
                    .next()
                    .context("rename record missing orig path field")?;
                FileEntry {
                    path: PathBuf::from(path),
                    orig_path: Some(PathBuf::from(orig)),
                    kind: ChangeKind::Renamed,
                    stage: stage_from_xy(xy),
                    adds: None,
                    dels: None,
                }
            }
            Some('u') => {
                let (_, path) = split_ordinary(record, 10)?;
                FileEntry {
                    path: PathBuf::from(path),
                    orig_path: None,
                    kind: ChangeKind::Conflicted,
                    stage: StageState::NA,
                    adds: None,
                    dels: None,
                }
            }
            Some('?') => FileEntry {
                path: PathBuf::from(record[2..].to_string()),
                orig_path: None,
                kind: ChangeKind::Untracked,
                stage: StageState::Untracked,
                adds: None,
                dels: None,
            },
            Some('!') => continue, // ignored files
            _ => continue,         // headers (`# …`) or unknown record types
        };
        // Conflicted overrides whatever kind_from_xy said for '1' records
        // (can't happen — u is its own record type — but keep sort stable).
        if entry.kind == ChangeKind::Conflicted {
            entry.stage = StageState::NA;
        }
        entries.push(entry);
    }
    Ok(entries)
}

/// Split an ordinary/rename/unmerged record: field 1 is XY, the path is
/// everything from field index `path_field` on (paths may contain spaces).
fn split_ordinary(record: &str, path_field: usize) -> Result<(&str, &str)> {
    let xy = record
        .split(' ')
        .nth(1)
        .context("porcelain record missing XY field")?;
    let mut start = 0;
    for _ in 0..path_field {
        start = record[start..]
            .find(' ')
            .map(|i| start + i + 1)
            .context("porcelain record too short")?;
    }
    Ok((xy, &record[start..]))
}

fn kind_from_xy(xy: &str) -> ChangeKind {
    let mut chars = xy.chars();
    let x = chars.next().unwrap_or('.');
    let y = chars.next().unwrap_or('.');
    // Prefer the index (staged) letter; fall back to worktree letter.
    let letter = if x != '.' { x } else { y };
    match letter {
        'A' => ChangeKind::Added,
        'D' => ChangeKind::Deleted,
        'R' => ChangeKind::Renamed,
        _ => ChangeKind::Modified,
    }
}

fn stage_from_xy(xy: &str) -> StageState {
    let mut chars = xy.chars();
    let x = chars.next().unwrap_or('.');
    let y = chars.next().unwrap_or('.');
    match (x != '.', y != '.') {
        (true, false) => StageState::Staged,
        (false, true) => StageState::Unstaged,
        (true, true) => StageState::Partial,
        (false, false) => StageState::Unstaged, // shouldn't appear
    }
}

/// Parse `git diff --name-status -z -M`: entries are
/// `status NUL path NUL` — renames are `Rnnn NUL orig NUL new NUL`.
fn parse_name_status(raw: &[u8]) -> Result<Vec<FileEntry>> {
    let text = String::from_utf8_lossy(raw);
    let mut fields = text.split('\0');
    let mut entries = Vec::new();
    while let Some(status) = fields.next() {
        if status.is_empty() {
            continue;
        }
        let letter = status.chars().next().unwrap_or('M');
        let (kind, path, orig_path) = match letter {
            'R' | 'C' => {
                let orig = fields.next().context("rename missing orig path")?;
                let new = fields.next().context("rename missing new path")?;
                (ChangeKind::Renamed, new, Some(PathBuf::from(orig)))
            }
            other => {
                let path = fields.next().context("name-status missing path")?;
                let kind = match other {
                    'A' => ChangeKind::Added,
                    'D' => ChangeKind::Deleted,
                    'U' => ChangeKind::Conflicted,
                    _ => ChangeKind::Modified,
                };
                (kind, path, None)
            }
        };
        entries.push(FileEntry {
            path: PathBuf::from(path),
            orig_path,
            kind,
            stage: StageState::NA,
            adds: None,
            dels: None,
        });
    }
    Ok(entries)
}

/// Parse `git diff --numstat -z`. Entry: `adds TAB dels TAB path NUL`;
/// renames instead end with `NUL orig NUL new NUL`. `-` = binary → None.
fn parse_numstat(raw: &[u8]) -> Vec<(PathBuf, Option<(u32, u32)>)> {
    let text = String::from_utf8_lossy(raw);
    let mut fields = text.split('\0');
    let mut out = Vec::new();
    while let Some(field) = fields.next() {
        if field.is_empty() {
            continue;
        }
        let mut cols = field.split('\t');
        let (Some(adds), Some(dels)) = (cols.next(), cols.next()) else {
            continue;
        };
        let path = match cols.next() {
            Some(p) if !p.is_empty() => p.to_string(),
            // rename form: path came as two extra NUL fields (orig, new)
            _ => {
                let _orig = fields.next();
                match fields.next() {
                    Some(new) => new.to_string(),
                    None => continue,
                }
            }
        };
        let stat = match (adds.parse::<u32>(), dels.parse::<u32>()) {
            (Ok(a), Ok(d)) => Some((a, d)),
            _ => None, // `-` = binary
        };
        out.push((PathBuf::from(path), stat));
    }
    out
}

/// Sum stats per path; binary (None) is contagious.
fn merge_stat(
    stats: &mut HashMap<PathBuf, Option<(u32, u32)>>,
    path: PathBuf,
    stat: Option<(u32, u32)>,
) {
    let slot = stats.entry(path).or_insert(Some((0, 0)));
    *slot = match (*slot, stat) {
        (Some((a1, d1)), Some((a2, d2))) => Some((a1 + a2, d1 + d2)),
        _ => None,
    };
}

/// Untracked file "stats": every line is an add. Skip binaries (NUL byte in
/// the first chunk) and files > 1 MiB.
fn untracked_stats(path: &Path) -> (Option<u32>, Option<u32>) {
    const MAX: u64 = 1024 * 1024;
    match std::fs::metadata(path) {
        Ok(meta) if meta.len() <= MAX => {}
        _ => return (None, None),
    }
    let Ok(bytes) = std::fs::read(path) else {
        return (None, None);
    };
    if bytes.iter().take(8192).any(|b| *b == 0) {
        return (None, None); // binary
    }
    let mut lines = bytes.iter().filter(|b| **b == b'\n').count() as u32;
    if !bytes.is_empty() && bytes.last() != Some(&b'\n') {
        lines += 1; // unterminated last line still counts
    }
    (Some(lines), Some(0))
}

/// Conflicted first, then directory-grouped lexicographic by path.
fn sort_entries(entries: &mut [FileEntry]) {
    entries.sort_by(|a, b| {
        let conflict = |e: &FileEntry| e.kind != ChangeKind::Conflicted;
        conflict(a)
            .cmp(&conflict(b))
            .then_with(|| a.path.cmp(&b.path))
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn porcelain_ordinary_records() {
        // staged-only, unstaged-only, partial
        let raw = b"1 M. N... 100644 100644 100644 abc def staged.rs\0\
                    1 .M N... 100644 100644 100644 abc def unstaged.rs\0\
                    1 MM N... 100644 100644 100644 abc def partial.rs\0";
        let entries = parse_porcelain_v2(raw).unwrap();
        assert_eq!(entries.len(), 3);
        assert_eq!(entries[0].stage, StageState::Staged);
        assert_eq!(entries[1].stage, StageState::Unstaged);
        assert_eq!(entries[2].stage, StageState::Partial);
        assert!(entries.iter().all(|e| e.kind == ChangeKind::Modified));
    }

    #[test]
    fn porcelain_rename_carries_orig_path() {
        let raw = b"2 R. N... 100644 100644 100644 abc def R100 new name.rs\0old name.rs\0";
        let entries = parse_porcelain_v2(raw).unwrap();
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].path, PathBuf::from("new name.rs"));
        assert_eq!(entries[0].orig_path, Some(PathBuf::from("old name.rs")));
        assert_eq!(entries[0].kind, ChangeKind::Renamed);
        assert_eq!(entries[0].stage, StageState::Staged);
    }

    #[test]
    fn porcelain_untracked_conflicted_ignored() {
        let raw = b"? new file.txt\0\
                    u UU N... 100644 100644 100644 100644 a b c conflict.rs\0\
                    ! ignored.log\0";
        let entries = parse_porcelain_v2(raw).unwrap();
        assert_eq!(entries.len(), 2);
        assert_eq!(entries[0].kind, ChangeKind::Untracked);
        assert_eq!(entries[0].path, PathBuf::from("new file.txt"));
        assert_eq!(entries[1].kind, ChangeKind::Conflicted);
        assert_eq!(entries[1].stage, StageState::NA);
    }

    #[test]
    fn numstat_parses_plain_binary_and_rename() {
        let raw = b"3\t1\tsrc/a.rs\0-\t-\timg.png\x000\t0\0old.rs\0new.rs\0";
        let stats = parse_numstat(raw);
        assert_eq!(stats.len(), 3);
        assert_eq!(stats[0], (PathBuf::from("src/a.rs"), Some((3, 1))));
        assert_eq!(stats[1], (PathBuf::from("img.png"), None));
        assert_eq!(stats[2], (PathBuf::from("new.rs"), Some((0, 0))));
    }

    #[test]
    fn name_status_kinds_and_rename() {
        let raw = b"M\0mod.rs\0A\0added.rs\0D\0gone.rs\0R087\0old.rs\0new.rs\0";
        let entries = parse_name_status(raw).unwrap();
        assert_eq!(entries.len(), 4);
        assert_eq!(entries[0].kind, ChangeKind::Modified);
        assert_eq!(entries[1].kind, ChangeKind::Added);
        assert_eq!(entries[2].kind, ChangeKind::Deleted);
        assert_eq!(entries[3].kind, ChangeKind::Renamed);
        assert_eq!(entries[3].path, PathBuf::from("new.rs"));
        assert_eq!(entries[3].orig_path, Some(PathBuf::from("old.rs")));
    }

    #[test]
    fn merge_stat_sums_and_binary_is_contagious() {
        let mut stats = HashMap::new();
        merge_stat(&mut stats, "a.rs".into(), Some((1, 2)));
        merge_stat(&mut stats, "a.rs".into(), Some((3, 4)));
        merge_stat(&mut stats, "b.png".into(), Some((5, 0)));
        merge_stat(&mut stats, "b.png".into(), None);
        assert_eq!(stats[&PathBuf::from("a.rs")], Some((4, 6)));
        assert_eq!(stats[&PathBuf::from("b.png")], None);
    }

    #[test]
    fn sort_puts_conflicts_first_then_paths() {
        let entry = |path: &str, kind| FileEntry {
            path: path.into(),
            orig_path: None,
            kind,
            stage: StageState::NA,
            adds: None,
            dels: None,
        };
        let mut entries = vec![
            entry("z/deep.rs", ChangeKind::Modified),
            entry("a.rs", ChangeKind::Modified),
            entry("m/conflict.rs", ChangeKind::Conflicted),
        ];
        sort_entries(&mut entries);
        let paths: Vec<_> = entries
            .iter()
            .map(|e| e.path.to_string_lossy().to_string())
            .collect();
        assert_eq!(paths, vec!["m/conflict.rs", "a.rs", "z/deep.rs"]);
    }
}

text:
//! The structured diff model: old-vs-new content as rows with syntax
//! highlighting, red/green line backgrounds, word-level emphasis, and folded
//! context — ported (simplified) from persiyanov/herdr-reviewr `diff.rs` (MIT).

use std::path::Path;

use ratatui::style::{Color, Style};
use ratatui::text::{Line, Span, Text};
use similar::{ChangeTag, TextDiff};

use super::highlight::{Highlighter, Rgb, Run};

/// A `[start, end)` run of char indices within a line, for word emphasis.
type CharRange = (u32, u32);

#[derive(Debug, Clone, PartialEq, Eq)]
enum Row {
    Context {
        old_no: u32,
        new_no: u32,
        runs: Vec<Run>,
    },
    Deletion {
        old_no: u32,
        runs: Vec<Run>,
        emphasis: Vec<CharRange>,
    },
    Insertion {
        new_no: u32,
        runs: Vec<Run>,
        emphasis: Vec<CharRange>,
    },
    /// A collapsed run of unchanged lines (kept, so a click can expand them).
    Fold { lines: Vec<Row> },
}

impl Row {
    fn text(&self) -> String {
        match self {
            Row::Context { runs, .. }
            | Row::Deletion { runs, .. }
            | Row::Insertion { runs, .. } => runs.iter().map(|r| r.text.as_str()).collect(),
            Row::Fold { .. } => String::new(),
        }
    }
}

/// The built document, ready to render. Folds can be expanded in place
/// (`unfold_at`), which rebuilds `text`.
pub struct DiffDoc {
    rows: Vec<Row>,
    flavor: String,
    default_fg: Rgb,
    /// Rendered line index → index into `rows`.
    line_rows: Vec<usize>,
    pub text: Text<'static>,
    /// First inserted line's new-file number (for the editor jump).
    pub first_change: Option<u32>,
    pub is_empty: bool,
    pub binary: bool,
}

impl DiffDoc {
    /// `(old_no, new_no)` of a rendered line (None for folds/out of range).
    pub fn numbers_of_line(&self, line: usize) -> Option<(Option<u32>, Option<u32>)> {
        let row = self.rows.get(*self.line_rows.get(line)?)?;
        match row {
            Row::Context { old_no, new_no, .. } => Some((Some(*old_no), Some(*new_no))),
            Row::Deletion { old_no, .. } => Some((Some(*old_no), None)),
            Row::Insertion { new_no, .. } => Some((None, Some(*new_no))),
            Row::Fold { .. } => None,
        }
    }

    /// The rendered line showing new-file line `no`, if visible (not folded).
    pub fn line_for_new(&self, no: u32) -> Option<usize> {
        (0..self.line_rows.len())
            .find(|&i| self.numbers_of_line(i).and_then(|(_, n)| n) == Some(no))
    }

    /// A rendered line's diff text: marker + content, no gutter. Empty for
    /// folds.
    pub fn marker_text_of_line(&self, line: usize) -> Option<String> {
        let row = self.rows.get(*self.line_rows.get(line)?)?;
        let marker = match row {
            Row::Deletion { .. } => "-",
            Row::Insertion { .. } => "+",
            Row::Context { .. } => " ",
            Row::Fold { .. } => return Some(String::new()),
        };
        Some(format!("{marker}{}", row.text()))
    }

    /// Expand the fold at rendered line `line` (if that line is a fold).
    /// Returns true when something unfolded (the text was rebuilt).
    pub fn unfold_at(&mut self, line: usize) -> bool {
        let Some(&row_idx) = self.line_rows.get(line) else {
            return false;
        };
        if !matches!(self.rows.get(row_idx), Some(Row::Fold { .. })) {
            return false;
        }
        let Row::Fold { lines } = self.rows.remove(row_idx) else {
            unreachable!();
        };
        self.rows.splice(row_idx..row_idx, lines);
        self.rebuild();
        true
    }

    fn rebuild(&mut self) {
        let (text, line_rows) = to_text(&self.rows, &Palette::new(&self.flavor), self.default_fg);
        self.text = text;
        self.line_rows = line_rows;
    }
}

/// Colors for the diff chrome, themed light or dark to match the syntax theme.
struct Palette {
    ins_bg: Rgb,
    del_bg: Rgb,
    ins_emph_bg: Rgb,
    del_emph_bg: Rgb,
    gutter: Rgb,
}

impl Palette {
    fn new(flavor: &str) -> Palette {
        if flavor == "light" {
            // GitHub-web-like tints.
            Palette {
                ins_bg: (0xe6, 0xff, 0xec),
                del_bg: (0xff, 0xeb, 0xe9),
                ins_emph_bg: (0xab, 0xf2, 0xbc),
                del_emph_bg: (0xff, 0xc0, 0xc0),
                gutter: (0x9a, 0xa0, 0xa6),
            }
        } else {
            // Catppuccin-ish tints for dark terminals.
            Palette {
                ins_bg: (0x1f, 0x3a, 0x2a),
                del_bg: (0x45, 0x23, 0x2f),
                ins_emph_bg: (0x30, 0x55, 0x3f),
                del_emph_bg: (0x6e, 0x34, 0x46),
                gutter: (0x6c, 0x70, 0x86),
            }
        }
    }
}

/// Context lines kept adjacent to each change; longer runs collapse to a fold.
const FOLD_MARGIN: usize = 3;

/// Build the full document from old and new file content.
pub fn build(path: &Path, old: &str, new: &str, hl: &Highlighter, flavor: &str) -> DiffDoc {
    if old.contains('\0') || new.contains('\0') {
        return DiffDoc {
            rows: Vec::new(),
            flavor: flavor.to_string(),
            default_fg: hl.default_fg,
            line_rows: Vec::new(),
            text: Text::default(),
            first_change: None,
            is_empty: false,
            binary: true,
        };
    }
    let ext = path.extension().and_then(|e| e.to_str());
    let old_lines = hl.highlight(old, ext);
    let new_lines = hl.highlight(new, ext);
    let line = |lines: &[Vec<Run>], i: usize| lines.get(i).cloned().unwrap_or_default();

    let mut rows = Vec::new();
    for change in TextDiff::from_lines(old, new).iter_all_changes() {
        match change.tag() {
            ChangeTag::Equal => {
                let (oi, ni) = (change.old_index().unwrap(), change.new_index().unwrap());
                rows.push(Row::Context {
                    old_no: oi as u32 + 1,
                    new_no: ni as u32 + 1,
                    runs: line(&new_lines, ni),
                });
            }
            ChangeTag::Delete => {
                let oi = change.old_index().unwrap();
                rows.push(Row::Deletion {
                    old_no: oi as u32 + 1,
                    runs: line(&old_lines, oi),
                    emphasis: Vec::new(),
                });
            }
            ChangeTag::Insert => {
                let ni = change.new_index().unwrap();
                rows.push(Row::Insertion {
                    new_no: ni as u32 + 1,
                    runs: line(&new_lines, ni),
                    emphasis: Vec::new(),
                });
            }
        }
    }

    let is_empty = !rows
        .iter()
        .any(|r| matches!(r, Row::Deletion { .. } | Row::Insertion { .. }));
    let first_change = rows.iter().find_map(|r| match r {
        Row::Insertion { new_no, .. } => Some(*new_no),
        _ => None,
    });

    compute_emphasis(&mut rows);
    let rows = collapse_context(rows);
    let (text, line_rows) = to_text(&rows, &Palette::new(flavor), hl.default_fg);
    DiffDoc {
        rows,
        flavor: flavor.to_string(),
        default_fg: hl.default_fg,
        line_rows,
        text,
        first_change,
        is_empty,
        binary: false,
    }
}

// ---- word-level emphasis ---------------------------------------------------

/// Two lines below this similarity are different lines, not one line edited.
const MIN_SIMILARITY: f32 = 0.7;

/// For each change block (a run of deletions followed by a run of insertions),
/// pair each deletion with its first similar-enough insertion and mark the
/// changed char ranges on both (git-delta's homolog inference, simplified).
fn compute_emphasis(rows: &mut [Row]) {
    let mut i = 0;
    while i < rows.len() {
        let del_start = i;
        while i < rows.len() && matches!(rows[i], Row::Deletion { .. }) {
            i += 1;
        }
        let ins_start = i;
        while i < rows.len() && matches!(rows[i], Row::Insertion { .. }) {
            i += 1;
        }
        pair_homologs(rows, del_start..ins_start, ins_start..i);
        if del_start == i {
            i += 1; // no change block here; step over the context row
        }
    }
}

fn pair_homologs(rows: &mut [Row], dels: std::ops::Range<usize>, inss: std::ops::Range<usize>) {
    let mut next_ins = inss.start;
    for d in dels {
        let old = rows[d].text();
        let mut p = next_ins;
        while p < inss.end {
            let new = rows[p].text();
            let (ratio, old_e, new_e) = word_emphasis(&old, &new);
            if ratio >= MIN_SIMILARITY {
                if let Row::Deletion { emphasis, .. } = &mut rows[d] {
                    *emphasis = old_e;
                }
                if let Row::Insertion { emphasis, .. } = &mut rows[p] {
                    *emphasis = new_e;
                }
                next_ins = p + 1;
                break;
            }
            p += 1;
        }
    }
}

/// Word-level similarity of `(old, new)` plus the changed char ranges on each
/// side, whitespace-trimmed and coalesced across pure-whitespace gaps.
fn word_emphasis(old: &str, new: &str) -> (f32, Vec<CharRange>, Vec<CharRange>) {
    let diff = TextDiff::from_words(old, new);
    let (mut old_ranges, mut new_ranges) = (Vec::new(), Vec::new());
    let (mut old_pos, mut new_pos) = (0u32, 0u32);
    for change in diff.iter_all_changes() {
        let len = change.value().chars().count() as u32;
        match change.tag() {
            ChangeTag::Equal => {
                old_pos += len;
                new_pos += len;
            }
            ChangeTag::Delete => {
                push_range(&mut old_ranges, old_pos, len);
                old_pos += len;
            }
            ChangeTag::Insert => {
                push_range(&mut new_ranges, new_pos, len);
                new_pos += len;
            }
        }
    }
    let old_e = trim_edges(coalesce(old_ranges, old), old);
    let new_e = trim_edges(coalesce(new_ranges, new), new);
    (diff.ratio(), old_e, new_e)
}

fn push_range(ranges: &mut Vec<CharRange>, pos: u32, len: u32) {
    if len == 0 {
        return;
    }
    match ranges.last_mut() {
        Some(last) if last.1 == pos => last.1 = pos + len,
        _ => ranges.push((pos, pos + len)),
    }
}

/// Merge ranges whose gap is all whitespace, so a changed phrase is one block.
fn coalesce(ranges: Vec<CharRange>, text: &str) -> Vec<CharRange> {
    let chars: Vec<char> = text.chars().collect();
    let mut out: Vec<CharRange> = Vec::new();
    for (start, end) in ranges {
        match out.last_mut() {
            Some(last)
                if chars[last.1 as usize..start as usize]
                    .iter()
                    .all(|c| c.is_whitespace()) =>
            {
                last.1 = end;
            }
            _ => out.push((start, end)),
        }
    }
    out
}

/// Shrink each range off leading/trailing whitespace; drop all-whitespace ones.
fn trim_edges(ranges: Vec<CharRange>, text: &str) -> Vec<CharRange> {
    let chars: Vec<char> = text.chars().collect();
    ranges
        .into_iter()
        .filter_map(|(mut a, mut b)| {
            while a < b && chars[a as usize].is_whitespace() {
                a += 1;
            }
            while b > a && chars[b as usize - 1].is_whitespace() {
                b -= 1;
            }
            (a < b).then_some((a, b))
        })
        .collect()
}

// ---- folding ---------------------------------------------------------------

/// Collapse runs of unchanged context beyond `FOLD_MARGIN` around each change.
fn collapse_context(rows: Vec<Row>) -> Vec<Row> {
    let n = rows.len();
    let mut keep = vec![false; n];
    for (i, row) in rows.iter().enumerate() {
        if matches!(row, Row::Context { .. }) {
            continue;
        }
        let lo = i.saturating_sub(FOLD_MARGIN);
        let hi = (i + FOLD_MARGIN).min(n.saturating_sub(1));
        keep[lo..=hi].iter_mut().for_each(|k| *k = true);
    }

    let mut out = Vec::new();
    let mut i = 0;
    while i < n {
        if keep[i] {
            out.push(rows[i].clone());
            i += 1;
            continue;
        }
        let start = i;
        while i < n && !keep[i] {
            i += 1;
        }
        if i - start > 1 {
            out.push(Row::Fold {
                lines: rows[start..i].to_vec(),
            });
        } else {
            out.extend(rows[start..i].iter().cloned());
        }
    }
    out
}

// ---- painting --------------------------------------------------------------

/// Chars of gutter + marker before the content on a change line
/// (`"{:>4}     "` or `"     {:>4}"` = 9, plus `"- "`/`"+ "` = 2).
const GUTTER_CHARS: u32 = 11;

/// Rows → ratatui text plus a rendered-line → row-index map (for clicks):
/// `old new marker` gutter, tinted backgrounds on change lines, stronger tint
/// on emphasized ranges.
fn to_text(rows: &[Row], p: &Palette, default_fg: Rgb) -> (Text<'static>, Vec<usize>) {
    let gutter_style = Style::new().fg(rgb(p.gutter));
    let mut lines = Vec::with_capacity(rows.len());
    let mut line_rows = Vec::with_capacity(rows.len());
    for (row_idx, row) in rows.iter().enumerate() {
        let line = match row {
            Row::Fold { lines: hidden } => Line::from(Span::styled(
                format!(
                    "      ▸ ⋯ {} unchanged lines — click to expand",
                    hidden.len()
                ),
                gutter_style,
            )),
            Row::Context {
                old_no,
                new_no,
                runs,
            } => {
                let mut spans = vec![Span::styled(
                    format!("{old_no:>4} {new_no:>4}   "),
                    gutter_style,
                )];
                spans.extend(paint(runs, None, &[], default_fg));
                Line::from(spans)
            }
            Row::Deletion {
                old_no,
                runs,
                emphasis,
            } => {
                let mut spans = vec![
                    Span::styled(format!("{old_no:>4}      "), gutter_style),
                    Span::styled(
                        "- ".to_string(),
                        Style::new().fg(Color::Red).bg(rgb(p.del_bg)),
                    ),
                ];
                spans.extend(paint(runs, Some(p.del_bg), emphasis, default_fg));
                line_with_bg(spans, p.del_bg)
            }
            Row::Insertion {
                new_no,
                runs,
                emphasis,
            } => {
                let mut spans = vec![
                    Span::styled(format!("     {new_no:>4}"), gutter_style),
                    Span::styled(
                        "+ ".to_string(),
                        Style::new().fg(Color::Green).bg(rgb(p.ins_bg)),
                    ),
                ];
                spans.extend(paint(runs, Some(p.ins_bg), emphasis, default_fg));
                line_with_bg(spans, p.ins_bg)
            }
        };
        let line = match row {
            Row::Deletion { emphasis, .. } if !emphasis.is_empty() => {
                repaint_emphasis(line, GUTTER_CHARS, emphasis, p.del_emph_bg)
            }
            Row::Insertion { emphasis, .. } if !emphasis.is_empty() => {
                repaint_emphasis(line, GUTTER_CHARS, emphasis, p.ins_emph_bg)
            }
            _ => line,
        };
        lines.push(line);
        line_rows.push(row_idx);
    }
    (Text::from(lines), line_rows)
}

/// Syntax runs → spans, with an optional background tint.
fn paint(
    runs: &[Run],
    bg: Option<Rgb>,
    _emphasis: &[CharRange],
    _default_fg: Rgb,
) -> Vec<Span<'static>> {
    runs.iter()
        .map(|r| {
            let mut style = Style::new().fg(rgb(r.color));
            if let Some(bg) = bg {
                style = style.bg(rgb(bg));
            }
            Span::styled(r.text.clone(), style)
        })
        .collect()
}

/// Extend a change line's background across the full width by styling the line.
fn line_with_bg(spans: Vec<Span<'static>>, bg: Rgb) -> Line<'static> {
    Line::from(spans).style(Style::new().bg(rgb(bg)))
}

/// Re-style the emphasized char ranges of a change line with a stronger
/// background. `prefix` is the gutter+marker char count before content.
fn repaint_emphasis(
    line: Line<'static>,
    prefix: u32,
    ranges: &[CharRange],
    emph_bg: Rgb,
) -> Line<'static> {
    let bg = rgb(emph_bg);
    let style = line.style;
    let mut out: Vec<Span<'static>> = Vec::new();
    let mut pos: u32 = 0; // char position across the whole line
    for span in line.spans {
        let chars: Vec<char> = span.content.chars().collect();
        let len = chars.len() as u32;
        let start = pos;
        // Split this span wherever emphasis ranges (shifted by prefix) cut it.
        let mut cursor = 0u32;
        while cursor < len {
            let abs = start + cursor;
            let content_pos = abs.saturating_sub(prefix);
            let in_emph = abs >= prefix
                && ranges
                    .iter()
                    .any(|&(a, b)| content_pos >= a && content_pos < b);
            // Find the run length with the same emphasis status.
            let mut end = cursor + 1;
            while end < len {
                let abs2 = start + end;
                let cp2 = abs2.saturating_sub(prefix);
                let in2 = abs2 >= prefix && ranges.iter().any(|&(a, b)| cp2 >= a && cp2 < b);
                if in2 != in_emph {
                    break;
                }
                end += 1;
            }
            let text: String = chars[cursor as usize..end as usize].iter().collect();
            let mut st = span.style;
            if in_emph {
                st = st.bg(bg);
            }
            out.push(Span::styled(text, st));
            cursor = end;
        }
        pos += len;
    }
    Line::from(out).style(style)
}

fn rgb((r, g, b): Rgb) -> Color {
    Color::Rgb(r, g, b)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn doc(old: &str, new: &str) -> DiffDoc {
        let hl = Highlighter::new("dark");
        build(&PathBuf::from("a.rs"), old, new, &hl, "dark")
    }

    #[test]
    fn empty_when_content_equal() {
        let d = doc("same\n", "same\n");
        assert!(d.is_empty);
        assert!(!d.binary);
    }

    #[test]
    fn binary_detected_by_nul() {
        let d = doc("ok\n", "bin\0ary\n");
        assert!(d.binary);
    }

    #[test]
    fn first_change_is_first_inserted_line() {
        let d = doc("a\nb\nc\n", "a\nb\nX\nc\n");
        assert_eq!(d.first_change, Some(3));
    }

    #[test]
    fn change_lines_carry_backgrounds_and_gutter_numbers() {
        let d = doc("alpha\nbeta\ngamma\n", "alpha\nBETA\ngamma\n");
        let flat: Vec<String> = d
            .text
            .lines
            .iter()
            .map(|l| l.spans.iter().map(|s| s.content.as_ref()).collect())
            .collect();
        let del = flat.iter().find(|l| l.contains("beta")).unwrap();
        let ins = flat.iter().find(|l| l.contains("BETA")).unwrap();
        assert!(del.contains("- "), "deletion marker: {del:?}");
        assert!(ins.contains("+ "), "insertion marker: {ins:?}");
        assert!(del.trim_start().starts_with('2'), "old line no: {del:?}");
        // Deletion line has the red tint as line style.
        let del_line = d
            .text
            .lines
            .iter()
            .find(|l| l.spans.iter().any(|s| s.content.contains("beta")));
        assert!(del_line.unwrap().style.bg.is_some());
    }

    #[test]
    fn long_context_folds() {
        let old: String = (0..40).map(|i| format!("line {i}\n")).collect();
        let new = old.replace("line 20", "LINE 20");
        let d = doc(&old, &new);
        let flat: String = d
            .text
            .lines
            .iter()
            .flat_map(|l| l.spans.iter().map(|s| s.content.as_ref()))
            .collect();
        assert!(flat.contains("unchanged lines"), "should fold: {flat}");
    }

    #[test]
    fn clicking_a_fold_expands_it() {
        let old: String = (0..40).map(|i| format!("line {i}\n")).collect();
        let new = old.replace("line 20", "LINE 20");
        let mut d = doc(&old, &new);
        let folded_len = d.text.lines.len();
        // First rendered line is the leading fold.
        assert!(d.unfold_at(0), "line 0 should be a fold");
        assert!(d.text.lines.len() > folded_len, "unfolding adds lines");
        // A content line is not a fold.
        assert!(!d.unfold_at(1));
    }

    #[test]
    fn word_emphasis_marks_changed_words() {
        let (ratio, old_e, new_e) = word_emphasis("let x = foo(a);", "let x = bar(a);");
        assert!(ratio >= MIN_SIMILARITY);
        assert_eq!(old_e.len(), 1);
        assert_eq!(new_e.len(), 1);
        let seg = |text: &str, (a, b): CharRange| -> String {
            text.chars()
                .skip(a as usize)
                .take((b - a) as usize)
                .collect()
        };
        // similar tokenizes on whitespace, so the changed "word" is foo(a);
        assert!(seg("let x = foo(a);", old_e[0]).contains("foo"));
        assert!(seg("let x = bar(a);", new_e[0]).contains("bar"));
        // the shared prefix is never emphasized
        assert!(old_e[0].0 > 0);
    }

    #[test]
    fn dissimilar_lines_get_no_emphasis() {
        let (ratio, _, _) = word_emphasis(
            "let start = scroll.min(len);",
            "return (row - inner.y) as usize;",
        );
        assert!(ratio < MIN_SIMILARITY);
    }
}

